.super-search-widget {
  --super-search-surface: #ffffff;
  --super-search-surface-soft: #ffffff;
  --super-search-border: #c7cfca;
  --super-search-text: #191b21;
  --super-search-muted: #5b676d;
  --super-search-accent: #083c5e;
  --super-search-accent-soft: #dbe7ee;
  --super-search-button: #0072ce;
  --super-search-button-hover: #005ea8;
  --super-search-shadow: 0 12px 28px rgba(25, 27, 33, 0.08);
  background: var(--super-search-surface);
  border: 1px solid var(--super-search-border);
  border-radius: 8px;
  box-shadow: var(--super-search-shadow);
  padding: 32px 28px 28px;
  position: relative;
}

.super-search-widget--compact {
  background: transparent;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  padding: 0;
}

.super-search-widget__form {
  margin: 0;
}

.super-search-widget__top-row {
  align-items: center;
  display: flex;
  justify-content: center;
  margin-bottom: 28px;
  text-align: center;
}

.super-search-widget__greeting {
  color: var(--super-search-text);
  flex: 0 1 auto;
  line-height: 1.25;
  margin: 0;
  max-width: 100%;
}

.super-search-widget__surface {
  background: transparent;
  border: 0;
  border-radius: 0;
  padding: 0;
}

.super-search-widget__controls {
  display: flex;
  width: 100%;
}

.super-search-widget__input-wrap {
  align-items: center;
  background: var(--super-search-surface-soft);
  border: 1px solid var(--super-search-border);
  border-radius: 6px;
  box-shadow: 0 6px 18px rgba(25, 27, 33, 0.06);
  display: flex;
  flex: 1 1 auto;
  min-height: 60px;
  padding: 6px 0 6px 22px;
  position: relative;
  transition: border-color 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease;
}

.super-search-widget__input-wrap:focus-within {
  background: #ffffff;
  border-color: var(--super-search-accent);
  box-shadow: 0 0 0 3px rgba(8, 60, 94, 0.12), 0 10px 24px rgba(25, 27, 33, 0.08);
}

.super-search-widget__input {
  background: transparent;
  border: 0;
  box-shadow: none;
  color: var(--super-search-text);
  flex: 1 1 auto;
  font: inherit;
  height: 42px;
  padding: 0;
  padding-right: 76px;
  position: relative;
  z-index: 1;
}

.super-search-widget__input.form-control:focus {
  border: 0;
  box-shadow: none;
}

.super-search-widget__input::placeholder {
  color: #707d84;
  opacity: 1;
}

.super-search-widget__filter-list {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: center;
  margin-top: 28px;
}

.super-search-widget__filter-pill {
  background: #ffffff;
  border: 1px solid #dfe5e2;
  border-radius: 10px;
  box-shadow: 0 2px 8px rgba(25, 27, 33, 0.04);
  color: #343a40;
  font: inherit;
  min-height: 44px;
  min-width: 92px;
  padding: 0 18px;
  transition: background-color 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease, color 0.15s ease;
}

.super-search-widget__filter-pill:hover,
.super-search-widget__filter-pill:focus {
  border-color: #c7cfca;
  box-shadow: 0 0 0 3px rgba(8, 60, 94, 0.08);
  color: var(--super-search-text);
  outline: 0;
}

.super-search-widget__filter-pill--active {
  background: #edf4fb;
  border-color: #d7e5f2;
  box-shadow: inset 0 0 0 1px rgba(8, 60, 94, 0.04);
  color: var(--super-search-text);
}

.super-search-widget__button {
  align-items: center;
  background: var(--super-search-button);
  border: 0;
  border-radius: 0 5px 5px 0;
  box-shadow: none;
  color: #ffffff;
  display: inline-flex;
  height: 100%;
  justify-content: center;
  min-width: 66px;
  padding: 0;
  position: absolute;
  right: 0;
  top: 0;
  transform: none;
  transition: transform 0.15s ease, box-shadow 0.2s ease, background 0.2s ease;
  width: 66px;
  z-index: 1;
}

.super-search-widget__button svg {
  display: block;
  fill: currentColor;
  height: 30px;
  width: 30px;
}

.super-search-widget__button-text {
  border: 0;
  clip: rect(0, 0, 0, 0);
  height: 1px;
  margin: -1px;
  overflow: hidden;
  padding: 0;
  position: absolute;
  width: 1px;
}

.super-search-widget__button:hover,
.super-search-widget__button:focus,
.super-search-widget__button:active {
  background: var(--super-search-button-hover);
  box-shadow: none;
  transform: none;
}

.super-search-widget--compact .super-search-widget__input-wrap {
  border-radius: 6px;
  box-shadow: 0 4px 14px rgba(25, 27, 33, 0.05);
  min-height: 44px;
  padding: 4px 0 4px 15px;
}

.super-search-widget--compact .super-search-widget__input {
  height: 34px;
  padding-right: 64px;
}

.super-search-widget--compact .super-search-widget__button {
  box-shadow: none;
  height: 100%;
  min-width: 48px;
  right: 0;
  width: 48px;
}

.super-search-widget--compact .super-search-widget__button svg {
  height: 22px;
  width: 22px;
}

@media (max-width: 767px) {
  .super-search-widget {
    border-radius: 8px;
    padding: 28px 20px 20px;
  }

  .super-search-widget__top-row {
    margin-bottom: 18px;
  }

  .super-search-widget__input-wrap,
  .super-search-widget__button {
    min-height: 48px;
  }

  .super-search-widget__input-wrap {
    min-height: 52px;
    padding-left: 18px;
  }

  .super-search-widget__input {
    height: 38px;
    padding-right: 72px;
  }

  .super-search-widget__button {
    height: 44px;
    min-width: 44px;
    right: 0;
    width: 52px;
  }

  .super-search-widget__button svg {
    height: 24px;
    width: 24px;
  }

  .super-search-widget__filter-list {
    gap: 8px;
    justify-content: flex-start;
    margin-top: 18px;
  }

  .super-search-widget__filter-pill {
    flex: 1 1 calc(50% - 8px);
    min-width: 0;
    padding: 0 12px;
  }

  .super-search-widget--compact {
    padding: 0;
  }
}

